var den=CALCULATE( [TPID Count], KEEPFILTERS( Account[Has Premier Unified] = "Yes" ), KEEPFILTERS( Account[Has CSDR] = "Yes" ) )
var num=CALCULATE( [TPID Count], KEEPFILTERS( Account[Has Premier Unified] = "Yes" ), KEEPFILTERS( Account[Has CSDR within 30 Days] = "Yes" ) )

RETURN DIVIDE(num,den,"")
